193	            }
194	            if(!view.isViable(field)){
195	                // System.out.println("STEPS COMPLETED: "+backupCounter);
196	                // uncomment this while optimizing for population stability
197	                Thread.currentThread().interrupt();
198	                if(backupCounter > SimulationInfo.HIGHEST_STEPS){
199	                    // If multiple instances of the simulation are created in the same session (for testing),
200	                    // the fields in SimulationInfo can be used for optimizing the default probabilities
201	                    SimulationInfo.HIGHEST_STEPS = backupCounter;
202	                    SimulationInfo.HIGHEST_STEP_PROBS = config.getPopulationRates();
203	                }
204	                playingSimulation = false;
