216	    public void simulateOneStep()
217	    {
218	        if(!playingSimulation){ return; }
219	        step++;
220	        environment.getTime().incrementTime();
221	        environment.getWeather().checkWeatherChange(step);
222	
223	
224	        // Provide space for newborn animals.
225	        List<Actor> newActors = new ArrayList<>();
226	        // Let all actors act.
227	        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
228	            Actor actor = it.next();
229	            if(actor instanceof Animal){
230	               if(((Animal) actor).isAwake(environment)) {
231	                   if(((Animal) actor).isDiseased() && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
232	                       ((Animal) actor).setDead();
233	                   }
234	                   actor.act(newActors, environment);
235	               }
236	            }
237	            else {
238	                actor.act(newActors, environment);
239	            }
240	
241	            if(actor instanceof Plant){
242	                if(step % ((Plant) actor).STEPS_PER_STAGE()==0){
243	                    ((Plant) actor).incrementGrowth();
244	                }
245	            }
246	
247	            if(! actor.isAlive()) {
248	                it.remove();
249	            }
250	
251	
252	
253	        }
254	        actors.addAll(newActors);
255	        plantGrassInPatches();
256	
257	        view.showStatus(step, environment.getWeather().getCurrentWeather().toString(), environment.getTime().getCurrentTimeString(), field);
258	    }
